function noSheet(){const L=S.parts.filter(p=>p.status==="out");return `<div class="sh" data-a="nox"><div data-keep="1"><div class="row"><h3>불참 ${L.length}명</h3><button class="link" data-a="nox">닫기</button></div><div class="pills" style="margin:10px 0 4px">${L.map(p=>`<span style="cursor:default">${esc(dnp(p))}</span>`).join("")}</div></div></div>`}
function unrSheet(){const L=unrL(),st=can("guest")||can("draw");return `<div class="sh" data-a="unrx"><div data-keep="1"><div class="row"><h3>아직 응답하지 않은 회원 ${L.length}명</h3><button class="link" data-a="unrx">닫기</button></div><div class="pills" style="margin:10px 0 12px">${L.map(m=>`<span style="cursor:default">${esc(m.displayName)}${m.uid?"":' <span class="sub" style="font-size:11px">미가입</span>'}</span>`).join("")}</div>${st?'<button data-a="unrShare">카톡으로 알리기</button><div class="sub center" style="margin-top:6px">참석 체크를 부탁하는 문구를 보낼 수 있어요</div>':""}</div></div>`}
const gOf=(k,p)=>{const c=S.cur,gm=c&&c.genderMode,m=S.mem.find(x=>mkey(x)===k);if(m&&m.gender)return m.gender;if(p&&p.gender)return p.gender;if(!m&&!p){const pp=(S.parts||[]).find(x=>key(x)===k);if(pp&&pp.gender)return pp.gender}return gm==="m"||gm==="f"?gm:""};
const gAnn=arr=>(arr||[]).map(q=>{const g=gOf(q.k);return g?{...q,g}:q});
const genPill=m=>S.cur.genderMode==="mixed"&&m.gender&&vis("gender")?`<span class="pill" style="background:#EEF0F8;color:#4A5A9A">${m.gender==="f"?"여":"남"}</span>`:"";
function gxFill(){const c=S.cur;if(S.pv||!can("result")||!c.genderMode)return;const L=S.games.filter(g=>!g.gx&&g.t1&&g.t2).map(g=>[g,gAnn(g.t1),gAnn(g.t2)]).filter(([,t1,t2])=>[...t1,...t2].every(p=>p.g)).slice(0,200);if(!L.length)return;
 const b=writeBatch(db);L.forEach(([g,t1,t2])=>b.update(doc(db,"games",g._id||g.id),{t1,t2,mtype:mtOfP(t1,t2),gx:1,updatedAt:serverTimestamp()}));b.commit().catch(()=>{})}
function addSheet(){const adm=S.cur.role==="admin",it=(a,ic,t,d)=>`<div class="li tap" data-a="${a}" style="min-height:58px"><span style="width:30px;font-size:20px">${ic}</span><span class="nm" style="white-space:normal"><b>${t}</b><div class="sub" style="font-weight:400">${d}</div></span></div>`;
 return `<div class="sh" data-a="addx"><div data-keep="1"><div class="row"><h3>${S.addNew?"이제 회원을 모아 볼까요?":"회원 추가"}</h3><button class="link" data-a="addx">${S.addNew?"나중에":"닫기"}</button></div>
${adm?`<div class="sub" style="margin:8px 0 4px">앱으로 가입</div><div class="list" style="margin:0 0 10px">${it("addInvite","📩","초대 링크 보내기","카톡으로 보내거나 QR로 보여줘요")}</div>`:""}
<div class="sub" style="margin:8px 0 4px">명단에만 등록 (미가입 회원)</div><div class="list" style="margin:0">${it("toOff","👤","한 명 추가","이름, 포지션을 입력해요")}${it("toBulk","📋","여러 명 한 번에","이름을 쭉 붙여넣어요")}${it("toBulkPhoto","📷","사진으로 추가","카톡 참여자 캡처나 명단 사진에서 읽어요 · 클럽 하루 5회")}</div>
<div class="sub" style="margin-top:10px">앱을 안 쓰는 회원도 명단에 넣어 대진과 기록에 포함할 수 있어요. 나중에 같은 이름으로 가입하면 기록이 이어져요.</div></div></div>`}
const welCard=()=>{const c=S.cur;let on=false;try{on=localStorage.getItem("cm_wel_"+c.id)==="1"}catch(e){}return on&&c.role!=="admin"?`<div class="card row" style="background:var(--tint);box-shadow:none;padding:12px 14px"><div><b>${esc(c.name)}에 오신 걸 환영해요!</b><div class="sub">다음 모임 참석 체크부터 해 보세요.</div>${(()=>{const me=S.mem.find(x=>x.uid===S.user.uid),nmx=me?me.displayName:S.profile.name;return S.mem.some(x=>!x.uid&&xn(x.displayName)===xn(nmx))?`<div class="sub" style="margin-top:4px">명단에 '${esc(nmx)}'(미가입) 기록이 있어요. 관리자가 연동하면 지난 기록이 내 기록으로 이어져요.</div>`:""})()}</div><span class="tap sub" data-a="welX" style="padding:6px 0 6px 12px">✕</span></div>`:""};
const qrSheet=()=>`<div class="sh" data-a="qrx"><div data-keep="1"><div class="row"><h3>초대 QR</h3><button class="link" data-a="qrx">닫기</button></div><img src="${S.qr}" alt="초대 QR" style="width:240px;height:240px;display:block;margin:10px auto"><div class="sub center">휴대폰 카메라로 찍으면 가입 화면이 열려요</div></div></div>`;
function infoCard(){const c=S.cur,adm=c.role==="admin",tierBlk=can("tiers")?`<div class="row" style="margin-bottom:8px"><span class="sub">Tier</span><div class="seg xs" data-k="te" style="width:170px"><div data-v="0" class="${S.form.te!=="1"?"on":""}">사용 안 함</div><div data-v="1" class="${S.form.te==="1"?"on":""}">사용</div></div></div>${S.form.te==="1"?`<div class="sub" style="margin:2px 0 4px">Tier 이름 <span class="qm" data-a="help" data-h="tier">?</span></div><input id="tn" maxlength="60" placeholder="국화부, 개나리부, 동배A, 동배B" value="${esc((c.tiers||[]).join(", "))}">`:""}`:"";
 if(!adm)return `<details class="card sd" data-sec="info" ${so("info")} style="padding:12px 14px"><summary><b>Tier</b></summary>${tierBlk}<button data-a="saveTier" style="margin:0">저장</button></details>`;
 return `<details class="card sd" data-sec="info" ${so("info")} style="padding:12px 14px"><summary><b>클럽 정보</b></summary>클럽 이름<input id="ci_n" maxlength="30" value="${esc(c.name||"")}">모임 장소<input id="ci_l" maxlength="40" value="${esc(c.meetingLocation||"")}">설명<textarea id="ci_d" rows="2" maxlength="100">${esc(c.description||"")}</textarea>
<div class="row" style="margin-bottom:8px"><span class="sub">공개 여부</span><div class="seg xs" data-k="civ" style="width:170px"><div data-v="public" class="${S.form.civ==="public"?"on":""}">공개</div><div data-v="private" class="${S.form.civ==="private"?"on":""}">비공개</div></div></div>
<div class="row" style="margin-bottom:8px"><span class="sub">가입 방법</span><div class="seg xs" data-k="cij" style="width:220px">${[["open","바로 가입"],["approval","승인"],["invite","초대만"]].map(([v,t])=>`<div data-v="${v}" class="${S.form.cij===v?"on":""}">${t}</div>`).join("")}</div></div>
<div class="row" style="margin-bottom:10px"><span class="sub">클럽 성별</span><div class="seg xs" data-k="gm" style="width:220px">${[["m","남성"],["f","여성"],["mixed","혼성"]].map(([v,t])=>`<div data-v="${v}" class="${S.form.gm===v?"on":""}">${t}</div>`).join("")}</div></div>${tierBlk}<button data-a="saveInfo" style="margin:0">저장</button></details>`}
const dlPast=d=>!!d&&ymd(new Date())>d&&!can("guest"),dlMsg=d=>`응답이 ${dlab(d)}에 마감됐어요. 바꾸려면 운영진에게 말해 주세요.`;
const evEff=m=>{const c=S.cur;return{start:m.start||c.regularStartTime||"13:00",end:m.end||c.regularEndTime||"16:00",courts:m.courts||c.regularCourtCount||3}};
const evLab=m=>m.kind==="extra"?(m.title?esc(m.title):"추가 모임"):"정기 모임";
const stPill=s=>s==="in"?'<span class="pill" style="background:var(--tint);color:var(--main)">✓ 참석</span>':s==="out"?'<span class="pill" style="background:#EEF0EE;color:var(--sub)">✕ 불참</span>':"";
function upList(){const L=meetingsAhead(S.cur,new Date(),60);return L.slice(1).filter(m=>m.kind==="extra"||m.monthly)}
async function upFetch(c){const L=upList().slice(0,5),u=S.user.uid;S.myUp=S.myUp||{};for(const m of L){try{const d=await getDoc(doc(db,"sessionParticipants",`${c.id}_${m.dk}_${u}`));S.myUp[m.dk]=d.exists()&&!d.data().deleted?d.data().status:""}catch(e){}}if(L.length&&S.screen==="clubHome"&&S.tab==="today")keepR()}
function heroUp(){const L=upList();if(!L.length)return"";const x=L[0],st=S.myUp||{},need=L.slice(0,5).some(m=>!st[m.dk]);return `<div class="tap" data-a="evAll" style="border-top:1px solid rgba(255,255,255,.2);margin-top:12px;padding-top:10px;font-size:14px">📅 ${dlab(x.dk)} ${x.monthly?"🏆 월례대회":evLab(x)}${L.length>1?` 외 ${L.length-1}개`:""}${need?' · <b style="color:var(--pt)">응답 필요</b>':""} ›</div>`}
function upCard(m){const L=upList();if(!L.length)return"";return `<div class="list" style="margin-top:-4px">${L.slice(0,2).map(x=>{const s=(S.myUp||{})[x.dk];return `<div class="li tap" data-a="evOpen" data-dk="${x.dk}"><span class="sub" style="width:84px;flex:none">${dlab(x.dk)}</span><span class="nm">${x.monthly?"🏆 월례대회":evLab(x)}</span>${s?stPill(s):`<span style="display:flex;gap:6px"><button class="sm" data-a="evResp" data-dk="${x.dk}" data-v="in">참석</button><button class="sm ghost" data-a="evResp" data-dk="${x.dk}" data-v="out">불참</button></span>`}</div>`}).join("")}</div><button class="link" data-a="evAll" style="display:block;margin:0 0 10px auto;font-size:13px">전체 일정 보기 ›</button>`}
const respBlock=m=>{if(!m||can("guest"))return"";const c=S.cur,md=(m.mode||c.mode||"round");if(m.closed)return"응답이 마감됐어요. 바꾸려면 운영진에게 말해 주세요.";if(m.deadline&&ymd(new Date())>m.deadline)return dlMsg(m.deadline);
 if(m.today&&md!=="record"){const e=evEff(m);if(mPhase(m,e.start,e.end,new Date())!=="before")return md==="queue"?"모임이 시작돼서 참석 응답은 닫혔어요. 도착하면 코트 현황에서 '도착'을 눌러 주세요.":"모임이 시작돼서 참석 응답이 닫혔어요. 바꾸려면 운영진에게 말해 주세요."}return""};
const phPill=m=>{if(!m)return"";const e=evEff(m),ph=mPhase(m,e.start,e.end,new Date());return (ph==="during"?' <span class="pill" style="background:var(--pt);color:var(--main)">진행 중</span>':"")+(m.closed?' <span class="pill" style="background:rgba(255,255,255,.2);color:#fff">응답 마감</span>':"")};
const heroCtl=m=>can("meeting")&&m&&m.dk?`<div style="margin-top:10px;display:flex;gap:16px;font-size:13px"><span class="tap" data-a="mClose" data-dk="${m.dk}" style="color:var(--pt);padding:4px 0">${m.closed?"응답 다시 열기":"응답 마감"}</span>${m.today?`<span class="tap" data-a="mEnd" data-dk="${m.dk}" style="color:var(--pt);padding:4px 0">모임 종료</span>`:""}</div>`:"";
const topW=gs=>{const tw=(S.cur.statsOff||[]).includes("mw")?[]:topK(Object.values(pTable((gs||[]).map(g=>({...g,t1:(g.t1||[]).map(p=>({...p,k:ck(p)})),t2:(g.t2||[]).map(p=>({...p,k:ck(p)}))}))).P).map(p=>({...p,x:p.w})));return{tw,twn:tw.map(r=>(S.mem.find(m=>mkey(m)===r.k)||{}).displayName||r.n)}};
function doneCard(){const D=S.done;if(!D)return"";const md=eff(S.cur).mode||"round",st=can("result"),my=D.my,mine=my.w+my.l+my.d;
 const {tw,twn}=topW(D.gs);
 return `<div class="card" style="padding:12px 14px"><div class="row"><b>오늘 모임 결과 · ${dlab(D.dk)}</b><button class="link" data-a="tab" data-k="games" style="font-size:13px">경기 탭에서 보기 ›</button></div>${tw.length?`<div style="margin-top:6px">${bdPill(isMonthly(S.cur,D.dk)?"월례대회 최다승":"오늘의 최다승")} <b>${twn.map(esc).join(", ")}</b> <span class="sub">${tw[0].w}승</span></div>`:""}<div class="sub" style="margin-top:4px">참석 ${D.att}명 · 경기 ${D.games}개${mine?` · <b style="color:var(--tx)">나 ${my.w}승${my.d?` ${my.d}무`:""} ${my.l}패</b>`:""}</div>
${st&&Object.keys(gGuests(D.gs)).length?`<div class="row" style="margin-top:8px"><span class="sub">게스트 ${Object.keys(gGuests(D.gs)).length}명</span><button class="sm ghost" data-a="gsOpen" data-dk="${D.dk}">게스트에게 기록 보내기</button></div>`:""}${st&&md==="round"&&D.missing?`<div class="row" style="margin-top:8px"><span class="sub" style="color:#C26A00">결과 미입력 ${D.missing}경기</span><button class="sm" data-a="tab" data-k="games">입력하기</button></div>`:""}${st&&md!=="round"?`<div class="row" style="margin-top:8px;justify-content:flex-end"><button class="sm ghost" data-a="gnew">결과 입력</button></div>`:""}${D.games?`<div class="row" style="margin-top:8px;justify-content:flex-end"><button class="sm ghost" data-a="doneShare">단톡방에 결과 공유</button></div>`:""}</div>`}
// 지난달 요약 카드(매달 1~15일, 닫으면 그달은 안 보임)
const rcYm=()=>prevYm(ymd(new Date()).slice(0,6)),rcOn=k=>{if(new Date().getDate()>15)return false;try{return localStorage.getItem("cm_rc_"+k)!==rcYm()}catch(e){return true}};
const rcCard=(k,R,extra)=>!R||!R.g?"":`<div class="card" style="padding:12px 14px"><div class="row"><b>${+rcYm().slice(4)}월 나의 기록</b><span class="tap sub" data-a="rcX" data-id="${k}" style="padding:4px 0 4px 12px">✕</span></div><div style="margin-top:4px"><b style="font-size:18px">${R.g}경기 ${R.w}승${R.d?` ${R.d}무`:""} ${R.l}패</b>${R.rate!=null?` <span class="sub">승률 ${R.rate}%</span>`:""}${R.diff?` <span style="font-size:12px;font-weight:600;color:${R.diff>0?"var(--main)":"#B3402A"}">${R.diff>0?"▲":"▼"} ${Math.abs(R.diff)}%p</span>`:""}</div>${R.top?`<div class="sub" style="margin-top:2px">가장 많이 만난 사람 <b style="color:var(--tx)">${esc(R.top.n)}</b> ${R.top.g}경기</div>`:""}${extra||""}</div>`;
const rcP=()=>rcOn("p")?rcCard("p",monthRecap(S.pg.map(g=>({date:g.date,r:pres(g),ppl:[...g.t1.slice(1),...g.t2].map(p=>p.n)})),rcYm())):"";
function rcClub(){const c=S.cur,k="c_"+c.id;if(!rcOn(k))return"";
 if(!S.rc||S.rc.id!==c.id){if(S.rcL!==c.id){S.rcL=c.id;const u=S.user.uid,ym=rcYm();syncQ(`${u}_cg_${c.id}`,"games",[["clubId","==",c.id]]).then(all=>{const gs=all.filter(g=>!g.deleted&&g.date&&g.scoreA!=null),rows=[];
  gs.forEach(g=>{const is=p=>p&&(p.k===u||ck(p)===u),a1=(g.t1||[]).some(is),b1=(g.t2||[]).some(is);if(!a1&&!b1)return;rows.push({date:g.date,r:g.scoreA===g.scoreB?"d":(g.scoreA>g.scoreB)===a1?"w":"l",ppl:[...(g.t1||[]),...(g.t2||[])].filter(p=>p&&!is(p)).map(p=>(S.mem.find(m=>mkey(m)===ck(p))||{}).displayName||p.n)})});
  S.rc={id:c.id,R:monthRecap(rows,ym),top:topW(gs.filter(g=>g.date.slice(0,6)===ym))}}).catch(()=>{S.rc={id:c.id}}).finally(()=>{S.rcL=null;if(S.screen==="clubHome"&&S.tab==="today"&&S.cur&&S.cur.id===c.id)keepR()})}return""}
 const {R,top}=S.rc;return rcCard(k,R,top&&top.tw.length?`<div class="sub" style="margin-top:2px">클럽 ${+rcYm().slice(4)}월 최다승 <b style="color:var(--tx)">${top.twn.map(esc).join(", ")}</b> ${top.tw[0].w}승</div>`:"")}
const guestTag=n=>{n=String(n||"").trim();return n&&!S.mem.some(m=>m.displayName===n)?"게스트":""};
const gNorm=()=>(S.games||[]).map(g=>({...g,t1:(g.t1||[]).map(p=>({...p,k:ck(p)})),t2:(g.t2||[]).map(p=>({...p,k:ck(p)}))}));
// 저장된 키가 회원과 연결 안 된 경기(게스트로 저장됐지만 지금은 회원 이름과 같음)
const lnkL=()=>(S.games||[]).filter(g=>!g.deleted&&[...(g.t1||[]),...(g.t2||[])].some(p=>p.k&&ck(p)!==p.k));
