 const e=evEff(m),P=E.parts||[],u=S.user.uid,mine=P.find(p=>p.uid===u),yes=P.filter(p=>p.status==="in"),no=P.filter(p=>p.status==="out"),un=S.mem.filter(x=>!P.some(p=>key(p)===mkey(x))),ed=can("meeting");
