async function gsMake(guests,dk,what){const c=S.cur,code=Array.from({length:8},()=>"ABCDEFGHJKLMNPQRSTUVWXYZ23456789"[Math.random()*32|0]).join("");
 try{await setDoc(doc(db,"guestShares",code),{clubId:c.id,clubName:c.name,date:dk,createdBy:S.user.uid,createdAt:serverTimestamp(),exp:Date.now()+30*864e5,guests});
  const url=`${location.origin}${location.pathname}?gs=${code}`,t=`[${c.name}] ${what}를 Court Manager 내 기록으로 가져가세요!\n링크를 열고 내 이름을 고르면 돼요 (30일 동안 열려요)\n${url}`;
  try{if(navigator.share){await navigator.share({text:t});return}await navigator.clipboard.writeText(t);toast("링크를 복사했어요. 카톡에 붙여넣어 주세요")}catch(e){}}catch(e){pop("링크를 만들지 못했습니다. Firestore 규칙이 게시되었는지 확인해 주세요.")}}
