club(el){pvEnd();statReset(1);S.cur=S.clubs.find(c=>c.id===el.dataset.id);S.tab="today";S.tvis={today:1};S.parts=[];S.mem=[];S.sess=null;S.q=null;S.cready=false;if(S.cur.status==="closed")return go("closed");go("clubHome");load().catch(()=>{}).finally(()=>{if(!S.cready){S.cready=true;render()}A.gAsk()})},
toClub(){go("clubHome");load()},
tab(el){S.tab=el.dataset.k;if(S.tab==="stats")statReset();if(!(S.tvis||{})[S.tab]){S.tvis={...(S.tvis||{}),[S.tab]:1};S.cready=false}if(S.tab==="settings")S.perm=Object.fromEntries(PERM.map(([k])=>[k,pm(k)]));if(S.tab==="settings"){S.soff=[...(S.cur.statsOff||[])];S.form.rkm=(S.cur.rankShow||{}).m||"all";S.form.rkn=(S.cur.rankShow||{}).n||5}if(S.tab==="settings")S.form={...S.form,te:S.cur.tierEnabled?"1":"0",qm:S.cur.mode||"round",qr:S.cur.qrule||"arrival",mon:(S.cur.monthly||{}).on?"1":"0",mvt:(S.cur.memberView||{}).tier||"all",mvp:(S.cur.memberView||{}).pos||"all",mvg:(S.cur.memberView||{}).gender||"all",gm:S.cur.genderMode||"",np:S.cur.noPlayEnabled===false?"0":"1",stype:S.cur.schedType||"weekly",civ:S.cur.visibility||"public",cij:S.cur.joinMethod||"open",days:[...(S.cur.regularDays||[])]};render();load().catch(()=>{}).finally(()=>{if(!S.cready){S.cready=true;render()}})},
