gfill(x,o){const ps=l=>l[0].p==="fore"&&l[1].p==="back"?0:l[0].p==="back"&&l[1].p==="fore"?1:2,all=[...x.t1,...x.t2];
  S.ge={...o,gs:[{gn:all.map(p=>(S.mem.find(m=>mkey(m)===p.k)||{}).displayName||p.n),ps:[ps(x.t1),ps(x.t2)],a:x.scoreA??"",b:x.scoreB??"",court:o.court||0}]};go("gedit")},
