gAdd(){snap();const g=S.ge,used=g.gs.map(x=>+x.court);let c=1;while(used.includes(c))c++;g.gs.push({gn:["","","",""],ps:[2,2],a:"",b:"",court:c});S.still=1;render();S.still=0},
gDelC(el){snap();S.ge.gs.splice(+el.dataset.gi,1);S.still=1;render();S.still=0},
