async gfixApply(n,to){const m=S.mem.find(x=>x.displayName===to);if(!m)return pop("회원을 찾지 못했어요.");const L=(S.games||[]).filter(g=>!g.deleted&&[...(g.t1||[]),...(g.t2||[])].some(p=>p.n===n&&isUnk(p)));
  if(!await ask(`'${n}'을(를) '${to}' 회원으로 바꿀까요?\n경기 ${L.length}개가 고쳐지고 회원 통계에 들어가요.`,"바꾸기","취소"))return;
  const fx=t=>(t||[]).map(p=>p.n===n&&isUnk(p)?{...p,k:mkey(m),n:m.displayName}:p);
  try{for(let i=0;i<L.length;i+=400){const b=writeBatch(db);L.slice(i,i+400).forEach(g=>{const t1=fx(g.t1),t2=fx(g.t2);b.update(doc(db,"games",g._id||g.id),{t1,t2,pk:[...t1,...t2].map(p=>p.k),updatedAt:serverTimestamp()})});await b.commit()}
   await load();go("gfix");toast(`${L.length}경기를 고쳤어요`)}catch(e){pop("고치지 못했습니다.")}},
