async pick(el){const ref=el.dataset.s,rr=()=>{S.still=1;render();S.still=0},isR=x=>x.split(":")[1]==="x";
  if(!S.sel||S.sel===ref){S.sel=S.sel===ref?null:ref;return rr()}
  const a=S.sel;S.sel=null;
  if((isR(a)&&isR(ref))||((isR(a)||isR(ref))&&a.split(":")[0]!==ref.split(":")[0])){S.sel=ref;return rr()}
  const rs=JSON.parse(JSON.stringify(S.dr.plan.rounds)),get=x=>{const q=x.split(":");return q[1]==="x"?{...pool().find(p=>p.k===q.slice(2).join(":"))}:rs[q[0]].games[q[1]]["t"+q[2]][q[3]]},put=(x,v)=>{const q=x.split(":");if(q[1]!=="x")rs[q[0]].games[q[1]]["t"+q[2]][q[3]]=v};
  const va=get(a),vb=get(ref);put(a,vb);put(ref,va);
  const {iv,st}=rinfo(S.cur),cx=R=>{const o=new Set();R.forEach((r,ri)=>{const t=r.time?tmin(r.time):st+ri*iv,iv2=r.time&&R[ri+1]&&R[ri+1].time?tmin(R[ri+1].time)-t:(r.time&&R[ri-1]&&R[ri-1].time?t-tmin(R[ri-1].time):iv),seen={};r.games.forEach(g=>{[...g.t1,...g.t2].forEach(x=>{if(seen[x.k])o.add(x.n+" 같은 회차 중복");seen[x.k]=1;const p=S.parts.find(q=>key(q)===x.k);if(p&&!(tmin(p.start)<=t&&tmin(p.end)>=t+iv2))o.add(x.n+" 참석 시간 밖");if((S.dr.excl[x.k]||[]).includes(r.n))o.add(x.n+" 제외 회차")});S.dr.pairs.forEach(([p,q])=>[g.t1,g.t2].forEach(m=>{const ks=m.map(x=>x.k);if(ks.includes(p)!==ks.includes(q))o.add("고정 페어 분리")}))})});return[...o]};
  const bef=new Set(cx(S.dr.plan.rounds)),add=cx(rs).filter(x=>!bef.has(x));
  if(add.length&&!await ask("조건 충돌\n"+add.slice(0,4).join("\n")+"\n그래도 변경할까요?"))return rr();
  S.dr.plan.rounds=rs;rr()},
