   gsel=S.form.gg??(S.cur.genderMode==="mixed"?"":S.cur.genderMode||""),id=m?`${c.id}_${d}_${mid(m)}`:`${c.id}_${d}_g${Date.now().toString(36)}`,ex=m?(m.uid?{uid:m.uid,name:m.displayName,guest:false}:{uid:null,mk:"o:"+m.oid,name:m.displayName,guest:false}):{uid:null,name:gname,guest:true,gender:gsel||""};
