  if(S.hSkip){S.hSkip=0;return}if(HPRE.includes(S.screen))return;
  if(S.gss){A.gsx()}else if(S.pvAsk){A.pvNo()}else if(S.pv&&S.screen==="clubHome"&&!(S.sd||S.mdt||S.pe||S.ms||S.nos||S.unr)){A.pvExit()}else if(newsItems().length&&!S.syncAsk&&S.cready!==false){A.newsOk()}else if(S.pick&&pickL().length){A.pickNo()}else if(S.addm||S.unr||S.nos||S.qr||S.pk||S.omrg||S.qarr||S.qend!=null||S.exp||S.mdt||S.sd||S.ms||S.pe||S.pmo||(S.ph&&S.ph.zoom)){S.addm=false;S.unr=S.nos=S.qr=S.pk=S.omrg=S.exp=S.mdt=S.sd=S.ms=S.pe=S.pmo=S.qend=null;S.qarr=false;if(S.ph)S.ph.zoom=0;S.still=1;render();S.still=0}
  else if(S.screen==="mode"){if(!S.exitArm){S.exitArm=1;toast("한 번 더 누르면 종료돼요")}const d=(history.state&&history.state.d)||0;if(d>0){S.hSkip=1;history.go(-d)}}
  else if(S.screen==="clubHome"&&S.tab!=="today"&&!S.pv)A.tab({dataset:{k:"today"}});
